  display: flex;
  align-items: center;
  gap: var(--tmt-ui-ref-space-2);
}
.reader-thread {
  display: grid;
  gap: var(--tmt-ui-ref-space-3);
  padding-bottom: var(--tmt-ui-ref-space-4);
  border-bottom: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule-soft);
}
.reader-thread[data-resolved] {
  opacity: 0.7;
}
.reader-thread[data-selected] {
  margin: calc(var(--tmt-ui-ref-space-2) * -1);
  padding: var(--tmt-ui-ref-space-2);
  border-radius: var(--tmt-ui-radius);
  background: var(--tmt-ui-surface-annotation-highlight);
}
.reader-thread-head {
  display: flex;
  align-items: flex-start;
  gap: var(--tmt-ui-ref-space-2);
}
.reader-thread-quote {
  flex: 1;
  color: var(--tmt-ui-color-secondary);
  font-size: var(--tmt-ui-ref-size-3);
}
.reader-turn {
  display: grid;
  grid-template-columns: 24px minmax(0, 1fr);
  gap: var(--tmt-ui-ref-space-2);
}
.reader-turn p {
  margin: 0;
}
.reader-who {
  font-weight: 600;
}
.reader-avatar {
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border-radius: var(--tmt-ui-radius-pill);
  background: var(--tmt-ui-surface-selection);
  font: 600 var(--tmt-ui-ref-size-1) / 1 var(--tmt-ui-font-mono);
}
.reader-new {
  margin: 0;
  color: var(--tmt-ui-color-waiting);
  font-size: var(--tmt-ui-ref-size-2);
  text-align: center;
}


.reader-states {
  position: fixed;
  left: calc(var(--tmt-ui-shell-rail-width, 0px) + 16px);
  bottom: 16px;
  z-index: 25;
  width: 300px;
  max-height: calc(100dvh - 32px);
  overflow: auto;
  font-size: var(--tmt-ui-ref-size-3);
}
.reader-states-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: var(--tmt-ui-ref-space-2) var(--tmt-ui-ref-space-3);
  border: 0;
  background: none;
  color: var(--tmt-ui-color-text);
  font: inherit;
  cursor: pointer;
}
.reader-states-head svg {
  width: 14px;
  transition: rotate var(--tmt-ui-motion-fast) var(--tmt-ui-motion-ease-out);
}
.reader-states-head svg[data-open='false'] {
  rotate: 180deg;
}
.reader-states-body {
  display: grid;
  gap: var(--tmt-ui-ref-space-2);
  padding: 0 var(--tmt-ui-ref-space-3) var(--tmt-ui-ref-space-3);
}
.reader-states-row {
  display: grid;
  gap: var(--tmt-ui-ref-space-1);
}
.reader-states-options {
  display: flex;
  flex-wrap: wrap;
  gap: var(--tmt-ui-ref-space-1);
}

@media (max-width: 760px) {
  .reader-wide {
    display: none;
  }
  .reader-subs-long {
    display: none;
  }
  .reader-subs-short {
    display: inline;
  }
  .reader-band-bar,
  .reader-tree {
    padding-inline: var(--tmt-ui-ref-space-4);
  }
  .reader-row {
    grid-template-columns: 16px 16px minmax(0, 1fr) 96px 32px;
  }
  .reader-grip,
  .reader-row-progress {
    display: none;
  }
  .reader-row-more {
    opacity: 1;
  }
  .reader-states {
    left: 8px;
    right: auto;
    width: min(300px, calc(100vw - 16px));
  }
  .reader-states:not([data-open]) {
    width: auto;
  }
  .reader-page {
    padding-inline: var(--tmt-ui-ref-space-4);
  }
}
.reader-composer-anchor {
  position: relative;
  height: 0;
  margin: 0;
}
.reader-composer-anchor > .reader-composer {
  top: calc(var(--tmt-ui-ref-space-2) * -1);
}


.reader-counter {
  padding: 0 var(--tmt-ui-ref-space-1);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.reader-report {
  margin-bottom: var(--tmt-ui-ref-space-3);
}

.reader-composer-stack {
  display: grid;
  gap: var(--tmt-ui-ref-space-1);
}
.reader-hint {
  margin: 0;
  font-size: var(--tmt-ui-ref-size-1);
}

}



@scope (.tmt-design-docs) {

.list-page {
  display: grid;
  gap: var(--tmt-ui-ref-space-4);
  padding: var(--tmt-ui-ref-space-5) var(--tmt-ui-ref-space-5) 120px;
}
.list-quiet {
  color: var(--tmt-ui-color-secondary);
  font-size: var(--tmt-ui-ref-size-3);
}
.list-pins {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--tmt-ui-ref-space-4);
  margin: 0;
  padding: 0;
  list-style: none;
}
.list-pin {
  position: relative;
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  align-items: center;
  gap: var(--tmt-ui-ref-space-3);
  min-height: 86px;
  padding: var(--tmt-ui-ref-space-3) var(--tmt-ui-ref-space-4);
}
.list-pin a {
  color: var(--tmt-ui-color-text);
  font-weight: 600;
  text-decoration: none;
}
.list-pin a:hover {
  text-decoration: underline;
}
.list-pin-icon {
  width: 28px;
  height: 28px;
  color: var(--tmt-ui-color-secondary);
}
.list-pin-mark {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 12px;
  height: 12px;
  color: var(--tmt-ui-color-secondary);
}
.list-pin-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--tmt-ui-ref-space-1);
  margin-top: var(--tmt-ui-ref-space-1);
}
.list-project {
  gap: var(--tmt-ui-ref-space-1);
  font-family: var(--tmt-ui-font-mono);
}
.list-project-dot {
  width: 6px;
  height: 6px;
  border-radius: var(--tmt-ui-radius-pill);
}
.list-count {
  color: var(--tmt-ui-color-secondary);
  font-variant-numeric: tabular-nums;
  font-weight: 400;
}
.list-tabs {
  justify-content: flex-start;
  border-radius: 0;
}
.list-tabs [data-slot='tabs-trigger'] {
  flex: none;
}

.list-controls {
  position: sticky;
  top: var(--tmt-ui-header-height);
  z-index: 4;
  display: flex;
  align-items: center;
  gap: var(--tmt-ui-ref-space-2);
  margin-inline: calc(var(--tmt-ui-ref-space-5) * -1);
  padding: 0 var(--tmt-ui-ref-space-5);
  transition:
    background-color var(--tmt-ui-motion-fast) var(--tmt-ui-motion-ease-out),
    border-color var(--tmt-ui-motion-fast) var(--tmt-ui-motion-ease-out);
  border-bottom: var(--tmt-ui-rule-width) solid transparent;
}
.list-controls[data-stuck] {
  padding-block: 10px;
  border-bottom-color: var(--tmt-ui-surface-rule);
  background: var(--tmt-ui-surface-paper);
}
.list-status {
  margin: 0;
}
.list-needs-dot {
  flex: none;
  width: 8px;
  height: 8px;
  border-radius: var(--tmt-ui-radius-pill);
  background: var(--tmt-ui-color-waiting);
}
.list-needs {
  gap: var(--tmt-ui-ref-space-1);
}
.list-needs-menu {
  min-width: 300px;
}
.list-needs-item > span:last-child {
  display: grid;
}
.list-loading {
  display: grid;
  gap: var(--tmt-ui-ref-space-2);
}
.list-skeleton {
  height: 44px;
}
.list-retry {
  margin-top: var(--tmt-ui-ref-space-2);
}
@media (max-width: 760px) {
  .list-page {
    padding-inline: var(--tmt-ui-ref-space-4);
  }
  .list-controls {
    margin-inline: calc(var(--tmt-ui-ref-space-4) * -1);
    padding-inline: var(--tmt-ui-ref-space-4);
  }
  .list-pins {
    grid-template-columns: minmax(0, 1fr);
  }
  .list-tabs {
    overflow-x: auto;
  }
}
.list-page > *,
.list-page [data-slot='tabs'] {
  min-width: 0;
}
.list-needs-label {
  display: inline;
}
@media (max-width: 760px) {
  .list-needs-label {
    display: none;
  }
}


.menu-manage {
  width: min(520px, calc(100vw - 32px));
}
.menu-shortcuts {
  display: grid;
  margin: 0;
  padding: 0;
  list-style: none;
}
.menu-shortcuts li {
  display: grid;
  grid-template-columns: 14px 16px minmax(0, 1fr) repeat(4, auto);
  align-items: center;
  gap: var(--tmt-ui-ref-space-2);
  min-height: 44px;
  border-bottom: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule-soft);
}
.menu-grip,
.menu-icon {
  width: 14px;
  color: var(--tmt-ui-color-secondary);
}
.menu-name {
  display: grid;
  min-width: 0;
}
.menu-name code {
  overflow: hidden;
  color: var(--tmt-ui-color-secondary);
  font: var(--tmt-ui-ref-size-2) var(--tmt-ui-font-mono);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.menu-settings {
  display: grid;
  gap: var(--tmt-ui-ref-space-5);
  max-width: 760px;
  padding: var(--tmt-ui-ref-space-6) var(--tmt-ui-ref-space-5) 120px;
}
.menu-h2 {
  margin: 0;
  font: 600 var(--tmt-ui-ref-size-7) / 1.3 var(--tmt-ui-font-display);
}
.menu-quiet {
  color: var(--tmt-ui-color-secondary);
  font-size: var(--tmt-ui-ref-size-3);
}
.menu-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--tmt-ui-ref-space-3);
}
.menu-defs {
  display: grid;
  margin: 0;
}
.menu-defs > div {
  display: flex;
  justify-content: space-between;
  gap: var(--tmt-ui-ref-space-4);
  padding: var(--tmt-ui-ref-space-3) 0;
  border-bottom: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule-soft);
}
.menu-defs dt {
  display: grid;
}
.menu-defs dd {
  margin: 0;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.menu-command {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: var(--tmt-ui-ref-space-3);
  padding: var(--tmt-ui-ref-space-1) var(--tmt-ui-ref-space-1) var(--tmt-ui-ref-space-1)
    var(--tmt-ui-ref-space-3);
  border-radius: var(--tmt-ui-radius);
  background: var(--tmt-ui-surface-code);
  font: var(--tmt-ui-ref-size-3) var(--tmt-ui-font-mono);
}

.list-controls > .tmt-rich-input {
  flex: 1;
  min-width: 0;
}
.list-tabs-row {
  border-bottom: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule);
}

.list-create-stuck {
  visibility: hidden;
}

.list-actions {
  display: flex;
  gap: var(--tmt-ui-ref-space-2);
  margin-bottom: var(--tmt-ui-ref-space-3);
}

.list-needs-filter {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  width: fit-content;
  box-sizing: border-box;
  min-height: 24px;
  margin-top: var(--tmt-ui-ref-space-3);
  padding: 4px 8px;
  border: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule);
  border-radius: var(--tmt-ui-radius-pill);
  background: var(--tmt-ui-surface-sheet);
  color: var(--tmt-ui-color-text);
  font: inherit;
  font-size: 11px;
  cursor: pointer;
}
.list-needs-filter[aria-pressed='true'] {
  background: var(--tmt-ui-surface-selection);
}
.list-needs-filter:focus-visible {
  outline: 2px solid var(--tmt-ui-color-focus);
  outline-offset: 1px;
}
.list-needs-filter-mark {
  color: var(--tmt-ui-color-waiting);
}

}



@scope (.tmt-design-docs) {

.tui-figure {
  margin: var(--tmt-ui-ref-space-5) 0;
  min-width: 0;
}
.tui-figure figcaption {
  display: flex;
  flex-wrap: wrap;
  gap: var(--tmt-ui-ref-space-2);
  margin-bottom: var(--tmt-ui-ref-space-2);
  font-size: var(--tmt-ui-ref-size-2);
}
.tui-frame-scroll {
  max-width: 100%;
  overflow: auto;
  border: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule);
  border-radius: var(--tmt-ui-radius);
}
.tui-frame-scroll:focus-visible {
  outline: var(--tmt-ui-focus-width) solid var(--tmt-ui-color-focus);
  outline-offset: var(--tmt-ui-ref-space-1);
}
tmt-tui-frame,
.tui-metrics {
  display: block;
  padding: var(--tmt-ui-ref-space-2);
  box-sizing: content-box;
  font: var(--tmt-ui-ref-size-2)/1.4 var(--tmt-ui-font-mono);
  font-variant-ligatures: none;
  white-space: pre;
}
.tui-frame-row {
  display: flex;
  height: 1.4em;
}
.tui-frame-row > span {
  flex: 0 0 1ch;
  width: 1ch;
  height: 1.4em;
}
.tui-controls {
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  gap: var(--tmt-ui-ref-space-3);
  margin-block: var(--tmt-ui-ref-space-4);
}
.tui-controls label {
  min-width: 0;
  max-width: 100%;
  display: grid;
  gap: var(--tmt-ui-ref-space-1);
  font-size: var(--tmt-ui-ref-size-2);
  color: var(--tmt-ui-color-secondary);
}
.tui-controls select {
  min-width: 0;
  box-sizing: border-box;
  max-width: 100%;
  border: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule);
  border-radius: var(--tmt-ui-radius);
  padding: var(--tmt-ui-ref-space-2);
  background: var(--tmt-ui-surface-paper);
  color: var(--tmt-ui-color-text);
  font: inherit;
}
.tui-controls select:focus-visible {
  outline: var(--tmt-ui-focus-width) solid var(--tmt-ui-color-focus);
}
.tui-reference {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--tmt-ui-ref-size-2);
}
.tui-reference th,
.tui-reference td {
  text-align: left;
  padding: var(--tmt-ui-ref-space-2);
  border-bottom: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule);
  vertical-align: top;
}
.tui-reference th {
  color: var(--tmt-ui-color-secondary);
  font-weight: 500;
}
.tui-reference-scroll {
  overflow-x: auto;
}
.tui-swatch {
  display: inline-block;
  width: 1em;
  height: 1em;
  margin-right: var(--tmt-ui-ref-space-2);
  vertical-align: middle;
  border: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule);
}
.tui-provenance {
  color: var(--tmt-ui-color-secondary);
  font-size: var(--tmt-ui-ref-size-2);
  overflow-wrap: anywhere;
}
.tui-section {
  min-width: 0;
}

.tui-sample {
  margin: var(--tmt-ui-ref-space-4) 0;
  min-width: 0;
}
.tui-sample > figcaption {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: var(--tmt-ui-ref-space-2);
  margin-bottom: var(--tmt-ui-ref-space-2);
  font-size: var(--tmt-ui-ref-size-2);
}
.tui-preview-cell {
  position: relative;
  min-width: 0;
  max-width: 100%;
}
.tui-metrics {
  position: absolute;
  display: inline-block;
  visibility: hidden;
  pointer-events: none;
}
.tui-source-link {
  display: inline-block;
  margin-top: var(--tmt-ui-ref-space-2);
  color: var(--tmt-ui-color-secondary);
  font-size: var(--tmt-ui-ref-size-2);
}
.tui-frame-page {
  margin: 0;
  overflow: auto;
}
.tui-frame-page .tui-figure {
  margin: 0;
}
.tui-frame-page figcaption {
  display: none;
}
.tui-frame-page .tui-frame-scroll {
  border: 0;
  border-radius: 0;
  overflow: visible;
}
.tui-component {
  min-width: 0;
}
.tui-part-list {
  display: grid;
  gap: var(--tmt-ui-ref-space-2);
  padding-left: var(--tmt-ui-ref-space-5);
  font-size: var(--tmt-ui-ref-size-2);
}
.tui-part-list code {
  white-space: nowrap;
}
.tui-key-list {
  display: flex;
  flex-wrap: wrap;
  gap: var(--tmt-ui-ref-space-3);
  padding: 0;
  list-style: none;
}
.tui-role-list {
  display: flex;
  flex-wrap: wrap;
  gap: var(--tmt-ui-ref-space-3);
  padding: 0;
  list-style: none;
}
.tui-missing {
  color: var(--tmt-ui-color-secondary);
  font-size: var(--tmt-ui-ref-size-2);
}

}



@scope (.tmt-design-docs) {
.tui-mock {
  max-width: 100%;
  min-width: 0;
  padding: var(--tmt-ui-ref-space-5);
}
.tui-mock-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--tmt-ui-ref-space-4);
}
.tui-mock-heading h1 {
  margin: 0;
  font-size: var(--tmt-ui-ref-size-7);
  font-weight: 500;
}
.tui-mock-heading p {
  margin: 0;
  font-size: var(--tmt-ui-ref-size-2);
}
.tui-mock .tui-controls {
  padding: var(--tmt-ui-ref-space-4);
  border: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule);
  border-radius: var(--tmt-ui-radius);
  background: var(--tmt-ui-surface-sheet);
}

.tui-mock .tui-states-toggle {
  border-radius: var(--tmt-ui-radius-pill);
}

}



@scope (.tmt-design-docs) {


.docs-hero > h3,
.docs-hero .docs-snippet,
.ds-example-label {
  display: none;
}

.docs-canvas > .docs-scene {
  width: 100%;
  min-width: 0;
  text-align: center;
}
.docs-scene > * {
  text-align: initial;
}
.docs-hero .docs-canvas {
  gap: 0.5rem;
}
:scope[data-chrome='hosted'] .docs {
  --docs-viewport: calc(100dvh - var(--design-header-height, var(--tmt-ui-header-height)));
}

@media (min-width: 761px) {
  :scope[data-chrome='hosted'] .docs {
    --docs-top: 0px;
  }
  :scope[data-chrome='hosted'] .docs-top {
    display: none;
  }
}
@media (max-width: 760px) {
  :scope[data-chrome='hosted'] .docs-nav {
    position: sticky;
    inset: auto;
    top: 56px;
    height: auto;
    max-height: 70dvh;
    overflow-y: auto;
    border-bottom: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule);
  }
}

}

