// The renderer supplies the real browser-ui Button on the page runtime's React.
export default ({ React, ui }) => {
  return function Button({ icon, children, 'busy-label': busyLabel, 'collapse-label': collapseLabel, ...props }) {
    return React.createElement(ui.Button, { ...props, busyLabel, collapseLabel }, icon, children);
  };
};

// Runtime 4 supplies the real browser-ui Switch.
export default ({ React, ui }) => function Switch({ checked, label, children, ...props }) {
  const [value, setValue] = React.useState(checked);
  React.useEffect(() => setValue(checked), [checked]);
  return React.createElement(ui.Switch, { ...props, 'aria-label': label, checked: value, onCheckedChange: setValue });
};

// Runtime 4 supplies the real browser-ui Checkbox.
export default ({ React, ui }) => function Checkbox({ checked, label, children, ...props }) {
  const [value, setValue] = React.useState(checked);
  React.useEffect(() => setValue(checked), [checked]);
  return React.createElement(ui.Checkbox, { ...props, 'aria-label': label, checked: value, onCheckedChange: setValue });
};

// Compose the real browser-ui Card parts supplied by runtime 4.
export default ({ React, ui }) => function Card({ heading, description, action, footer, children }) {
  const h = React.createElement;
  return h(ui.Card, null,
    heading !== undefined && h(ui.CardHeader, null,
      h(ui.CardTitle, null, heading),
      description !== undefined && h(ui.CardDescription, null, description),
      action !== undefined && h(ui.CardAction, null, action)),
    h(ui.CardContent, null, children),
    footer !== undefined && h(ui.CardFooter, null, footer));
};

// Compose the real browser-ui Alert parts supplied by runtime 4.
export default ({ React, ui }) => function Alert({ variant, heading, children }) {
  const h = React.createElement;
  return h(ui.Alert, { variant }, heading !== undefined && h(ui.AlertTitle, null, heading),
    h(ui.AlertDescription, null, children));
};

// Compose the real browser-ui Empty parts supplied by runtime 4.
export default ({ React, ui }) => function Empty({ heading, description, icon, children }) {
  const h = React.createElement;
  return h(ui.Empty, null, h(ui.EmptyHeader, null,
    icon !== undefined && h(ui.EmptyMedia, null, icon),
    h(ui.EmptyTitle, null, heading),
    description !== undefined && h(ui.EmptyDescription, null, description)),
    children !== undefined && h(ui.EmptyContent, null, children));
};

// The real browser-ui Tabs parts own keyboard and selection behavior.
export default ({ React, ui }) => function Tabs({ items = '', value, actions, children }) {
  const list = items.split(',').map((item) => item.trim()).filter(Boolean);
  const [selected, setSelected] = React.useState(value ?? list[0]);
  React.useEffect(() => { if (value !== undefined) setSelected(value); }, [value]);
  const h = React.createElement;
  const tabList = h(ui.TabsList, null, ...list.map((item) => h(ui.TabsTrigger, { key: item, value: item }, item)));
  return h(ui.Tabs, { value: selected, onValueChange: setSelected },
    actions ? h(ui.TabsBar, { actions }, tabList) : tabList,
    children);
};

export default ({ React, ui }) => ({ label = 'Blocks', kind = 'insert', placement, items = '', active, hints }) => {
  const h = React.createElement;
  const names = items.split(',').map((item) => item.trim()).filter(Boolean);
  return h(ui.BlockMenu, { label, kind, placement },
    ...names.map((name) => h(ui.BlockMenuItem, { key: name, active: name === (active ?? names[0]) }, name)),
    hints && h(ui.BlockMenuFooter, null, h('span', null, h(ui.BlockKbd, null, '↑↓'), ' choose'),
      h('span', null, h(ui.BlockKbd, null, 'Enter'), ' insert'), h('span', null, h(ui.BlockKbd, null, 'Esc'), ' close')));
};

export default ({ React, ui }) => function Todo({ checked, children, ...props }) {
  const [value, setValue] = React.useState(checked);
  React.useEffect(() => setValue(checked), [checked]);
  return React.createElement(ui.TodoBlock, { ...props, checked: value, label: 'To-do', onCheckedChange: setValue }, children);
};

export default ({ React, ui }) => ({ label = 'Table', columns = '', rows = '', 'hide-narrow': hide = '' }) => {
  const hidden = new Set(hide.split(',').map((item) => item.trim()));
  return React.createElement(ui.TableBlock, { label,
    columns: columns.split(',').map((name) => name.trim()).filter(Boolean).map((name) => ({ name, hideNarrow: hidden.has(name) })),
    rows: rows ? rows.split(';').map((row) => row.split('|').map((cell) => cell.trim())) : [] });
};

// Read the authored text slot, then let the real CodeBlock own its rendering.
export default ({ React, ui }) => function CodeBlock({ children, ...props }) {
  const ref = React.useRef(null);
  const [text, setText] = React.useState('');
  React.useLayoutEffect(() => { if (ref.current) setText(ref.current.textContent ?? ''); }, [children]);
  return React.createElement(React.Fragment, null,
    React.createElement('span', { ref, hidden: true }, children), React.createElement(ui.CodeBlock, { ...props, text }));
};

// The host-provided part is the same PageListTable used by Colab, admitted by runtime 3.
export default ({ React, html, parts }) => {
  const Table = parts.PageListTable;
  return function PageView(props) {
    const [groupBy, setGroupBy] = React.useState(props['group-by'] || 'state');
    const [collapsed, setCollapsed] = React.useState(new Set());
    const [selected, setSelected] = React.useState(new Set(props.selected ? [props.selected] : []));
    const columns = [
      ['title', 'Page'],
      ['state', 'State'],
      ['progress', 'Sub-pages'],
      ['owner', 'Owner'],
      ['updated', 'Updated'],
    ];
    const parse = (text, fallback) => {
      try {
        const value = JSON.parse(text || '');
        return Array.isArray(value) ? value : fallback;
      } catch {
        return fallback;
      }
    };
    const [visible, setVisible] = React.useState(() => {
      const requested = parse(
        props.columns,
        columns.map(([id]) => id),
      );
      return columns.map(([id]) => id).filter((id) => id === 'title' || requested.includes(id));
    });
    const [filters, setFilters] = React.useState(() =>
      parse(props.filters, [])
        .filter(
          (filter) =>
            filter &&
            ['project', 'state', 'owner'].includes(filter.field) &&
            typeof filter.value === 'string',
        )
        .slice(0, 20),
    );
    let raw;
    try {
      raw = JSON.parse(props.rows || '[]');
    } catch {
      raw = [];
    }
    const rows = (Array.isArray(raw) ? raw : [])
      .slice(0, 200)
      .filter((item) => item && typeof item.id === 'string' && typeof item.name === 'string')
      .map((item) => ({
        id: item.id,
        name: item.name,
        title: item.name,
        projects: Array.isArray(item.projects)
          ? item.projects.filter((v) => typeof v === 'string')
          : [],
        stage: typeof item.stage === 'string' ? { id: item.stage, label: item.stage } : undefined,
        updated: typeof item.updated === 'string' ? item.updated : '',
        updatedAt: typeof item.updatedAt === 'number' ? item.updatedAt : undefined,
        subpages:
          item.subpages &&
          Number.isSafeInteger(item.subpages.done) &&
          Number.isSafeInteger(item.subpages.total) &&
          item.subpages.total > 0 &&
          item.subpages.done >= 0 &&
          item.subpages.done <= item.subpages.total
            ? item.subpages
            : undefined,
        needsYou: item.needsYou === true,
        author: typeof item.author === 'string' ? item.author : '',
        access: typeof item.access === 'string' ? item.access : 'Team',
      }));
    const group = (row) =>
      groupBy === 'state'
        ? row.stage?.label || 'No stage'
        : groupBy === 'project'
          ? row.projects[0] || 'No project'
          : groupBy === 'owner'
            ? row.author || 'No owner'
            : '';
    const groups = new Map();
    for (const row of rows) {
      const key = group(row);
      groups.set(key, [...(groups.get(key) || []), row]);
    }
    const ordered = [...groups.values()].flat();
    const toggle = (id) =>
      setCollapsed((current) => {
        const next = new Set(current);
        if (next.has(id)) next.delete(id);
        else next.add(id);
        return next;
      });
    return html`<section className="tmt-page-view" aria-label=${props.label || 'Pages'}>
      <div className="tmt-page-view-toolbar">
        <strong>${props.label || 'Pages'}</strong>
        ${filters.map(
          (filter, index) => html`<button
            type="button"
            key=${index}
            aria-label=${`Remove ${filter.field}: ${filter.value} filter`}
            onClick=${() => setFilters((old) => old.filter((_, at) => at !== index))}
          >
            ${filter.field}: ${filter.value} ×
          </button>`,
        )}
        <label
          >Group by
          <select value=${groupBy} onChange=${(event) => setGroupBy(event.target.value)}>
            <option value="state">State</option>
            <option value="project">Project</option>
            <option value="owner">Owner</option>
            <option value="none">None</option>
          </select></label
        >
        <details
          onKeyDown=${(event) => {
            if (event.key === 'Escape') {
              event.preventDefault();
              event.currentTarget.open = false;
              event.currentTarget.querySelector('summary')?.focus();
            }
          }}
        >
          <summary>Columns ${visible.length}/${columns.length}</summary>
          <div className="tmt-page-view-columns" role="menu" aria-label="Visible columns">
            ${columns.map(
              ([id, label]) => html`<label key=${id}
                ><input
                  type="checkbox"
                  role="menuitemcheckbox"
                  aria-checked=${visible.includes(id)}
                  checked=${visible.includes(id)}
                  disabled=${id === 'title'}
                  onChange=${(event) =>
                    setVisible((current) =>
                      event.target.checked
                        ? [...current, id]
                        : current.filter((value) => value !== id),
                    )}
                />${label}</label
              >`,
            )}
          </div>
        </details>
      </div>
      <${Table}
        rows=${ordered}
        state=${props.state && props.state !== 'auto' ? props.state : ordered.length ? 'ready' : 'empty'}
        empty="No matching pages"
        error="Page list unavailable"
        pageView=${true}
        livePageView=${!props.rows}
        density=${props.density || 'compact'}
        selected=${selected}
        onSelectedChange=${props.selectable ? setSelected : undefined}
        visibleColumns=${visible}
        pageViewOptions=${{ filters, sort: props.sort || 'updated', limit: Math.max(1, Math.min(200, Number(props.limit) || 20)) }}
        rowGroup=${groupBy === 'none' ? undefined : (row) => ({ id: group(row), label: group(row) })}
        collapsedGroups=${collapsed}
        onGroupToggle=${toggle}
      />
    </section>`;
  };
};

