// The host supplies only the admitted display metadata for this page id.
export default ({ React, html, data, prefix }) => {
  const usePage = data.page;
  const Badge = `${prefix}-badge`;
  return function WorkBundle(props) {
    const [work, setWork] = React.useState(props.work || '');
    React.useEffect(() => setWork(props.work || ''), [props.work]);
    const observed = usePage(props.page || '');
    const page = /^[A-Za-z0-9_-]{1,128}$/.test(props.page || '') ? observed : null;
    let tickets;
    try {
      tickets = JSON.parse(props.tickets || '[]');
    } catch {
      tickets = [];
    }
    tickets = (Array.isArray(tickets) ? tickets : [])
      .slice(0, 20)
      .filter(
        (item) =>
          item &&
          typeof item.label === 'string' &&
          typeof item.href === 'string' &&
          /^https:\/\/github\.com\//.test(item.href),
      );
    return html`<article className="tmt-block-work" data-page=${props.page}>
      <header>
        ${props.number && html`<span className="tmt-block-work-number">${props.number}</span>`}
        <div>
          ${
            page === undefined
              ? html`<span role="status">Loading page…</span>`
              : page === null
                ? html`<span>Page not found</span>`
                : html`<a href=${page.href}>${page.title}</a>`
          }
          ${
            page &&
            html`<div className="tmt-block-work-meta">
              ${(page.projects || []).map((project) => html`<${Badge} key=${project} variant="outline">${project}<//>`)}
              ${page.stage && html`<${Badge} variant="outline">${page.stage}<//>`}${page.owner && html`<span>${page.owner}</span>`}
              ${page.needsYou && html`<span><span className="tmt-block-work-attention">◆</span> Needs you</span>`}
              ${page.updated && html`<span>${page.updated}</span>`}
            </div>`
          }
        </div>
      </header>
      ${page?.summary && html`<p>${page.summary}</p>`}
      ${
        (work || props.editable) &&
        html`<div className="tmt-block-work-field">
          <span>Work</span>
          ${
            props.editable
              ? html`<textarea
                  aria-label="Work"
                  value=${work}
                  onInput=${(event) => {
                    const value = event.target.value;
                    setWork(value);
                    event.currentTarget.dispatchEvent(
                      new CustomEvent('tmt-work-change', { bubbles: true, detail: { value } }),
                    );
                  }}
                />`
              : html`<p>${work}</p>`
          }
        </div>`
      }
      ${
        tickets.length > 0 &&
        html`<div className="tmt-block-work-tickets">
          <span>GitHub</span>
          ${tickets.map((ticket) => html`<a key=${ticket.href} href=${ticket.href}>${ticket.label}</a>`)}
        </div>`
      }
    </article>`;
  };
};

