}
.tmt-block-doc-body {
  --tmt-block-gutter: 56px;
  --tmt-block-gap: 14px;
  position: relative;
  padding-inline-start: var(--tmt-block-gutter);
}
.tmt-block {
  position: relative;
  min-width: 0;
  margin-inline: -8px;
  padding: 2px 8px;
  border-radius: var(--tmt-ui-radius-s);
  outline: none;
}
.tmt-block + .tmt-block {
  margin-top: var(--tmt-block-gap);
}
