  max-height: 480px;
  overflow: auto;
}
.tmt-block-table .tmt-ui-table {
  width: 100%;
}
.tmt-block-table [data-nowrap] {
  white-space: nowrap;
}
.tmt-block-card {
  margin: 0;
  padding: 16px;
  border: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule);
  border-radius: var(--tmt-ui-radius-l);
  background: var(--tmt-ui-surface-sheet);
}
.tmt-block-card[data-variant='section'] {
  padding: 0;
  border: 0;
  background: none;
}
.tmt-block-card-head {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 12px;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 12px;
}
.tmt-block-card-title {
  min-width: 0;
  margin: 0;
  font-size: 16px;
  font-weight: 600;
  overflow-wrap: anywhere;
}
.tmt-block-card[data-variant='section'] .tmt-block-card-title {
  color: var(--tmt-ui-color-secondary);
  font-size: var(--tmt-ui-caption-size);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.tmt-block-card-meta {
  color: var(--tmt-ui-color-secondary);
  font-size: var(--tmt-ui-caption-size);
  white-space: nowrap;
}
.tmt-block-card-body {
  display: grid;
  gap: 10px;
  min-width: 0;
}
.tmt-block-card-body > .tmt-block {
  margin-top: 0;
}
.tmt-block-callout > .tmt-ui-notice {
  margin: 0;
}
.tmt-block-code {
  overflow: hidden;
  border: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule);
  border-radius: var(--tmt-ui-radius);
}
.tmt-block-code-head {
  display: flex;
  gap: 8px;
  align-items: center;
  min-width: 0;
  min-height: 32px;
  padding: 0 4px 0 12px;
  border-bottom: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule);
  background: var(--tmt-ui-surface-paper);
  color: var(--tmt-ui-color-secondary);
  font-size: var(--tmt-ui-caption-size);
}
.tmt-block-code-file {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  font-family: var(--tmt-ui-font-mono);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.tmt-block-code-copy {
  display: inline-flex;
  gap: 4px;
  align-items: center;
  min-height: 28px;
  padding: 0 6px;
  border: 0;
  border-radius: var(--tmt-ui-radius-s);
  background: none;
  color: inherit;
  font: inherit;
  cursor: pointer;
}
.tmt-block-code-copy:hover {
  background: var(--tmt-ui-surface-hover);
  color: var(--tmt-ui-color-text);
}
.tmt-block-code-copy:focus-visible {
  outline: var(--tmt-ui-focus-width) solid var(--tmt-ui-color-focus);
}
.tmt-block-code-body {
  margin: 0;
  padding: 10px 12px;
  background: var(--tmt-ui-surface-code);
  font: 13px / 1.55 var(--tmt-ui-font-mono);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.tmt-block-code-body[data-wrap='false'] {
  overflow-x: auto;
  white-space: pre;
}
.tmt-block-mention {
  display: inline-flex;
  gap: 4px;
  align-items: center;
  max-width: 100%;
  padding: 0 6px;
  border-radius: var(--tmt-ui-radius-s);
  background: var(--tmt-ui-surface-selection);
  color: var(--tmt-ui-color-selected-text);
  font-size: 0.92em;
  text-decoration: none;
  vertical-align: baseline;
  white-space: nowrap;
}
.tmt-block-mention-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
a.tmt-block-mention:hover {
  text-decoration: underline;
}
a.tmt-block-mention:focus-visible {
  outline: var(--tmt-ui-focus-width) solid var(--tmt-ui-color-focus);
}
.tmt-block-toast {
  display: inline-flex;
  gap: 12px;
  align-items: center;
