// The page owns answer persistence; the block emits its answer on the originating form.
export default ({ React, html, prefix }) =>
  function QuestionBlock(props) {
    const Button = `${prefix}-button`;
    const id = React.useId();
    const input = React.useRef(null);
    const otherInput = React.useRef(null);
    const [selected, setSelected] = React.useState([]);
    const [other, setOther] = React.useState(false);
    const [value, setValue] = React.useState('');
    const [expanded, setExpanded] = React.useState(false);
    let choices;
    try {
      choices = JSON.parse(props.choices || '[]');
    } catch {
      choices = [];
    }
    choices = (Array.isArray(choices) ? choices : [])
      .filter((choice) => typeof choice === 'string')
      .slice(0, 20);
    const kind = props.kind || 'single';
    React.useEffect(() => {
      if (other) input.current?.focus();
    }, [other]);
    if (props.state === 'dismissed')
      return html`<div className="tmt-block-question-dismissed">Question removed</div>`;
    if (props.state === 'answered' && !expanded)
      return html`<button
        type="button"
        className="tmt-block-question-answered"
        aria-expanded="false"
        onClick=${() => setExpanded(true)}
      >
        ✓ ${props.label} ${props.answer}
      </button>`;
    const valid =
      kind === 'short'
        ? !!value.trim()
        : (selected.length > 0 || other) && (!other || !!value.trim());
    const choose = (choice, checked) => {
      if (kind === 'single') {
        setSelected([choice]);
        setOther(false);
        setValue('');
      } else
        setSelected((old) => (checked ? [...old, choice] : old.filter((item) => item !== choice)));
    };
    const submit = (event) => {
      event.preventDefault();
      if (!valid) return;
      event.currentTarget.dispatchEvent(
        new CustomEvent('tmt-question-answer', {
          bubbles: true,
          detail: {
            choices: selected,
            ...(other ? { other: value.trim() } : {}),
            ...(kind === 'short' ? { text: value.trim() } : {}),
          },
        }),
      );
    };
    const key = (event) => {
      if (event.nativeEvent.isComposing) return;
      if ((event.metaKey || event.ctrlKey) && event.key === 'Enter') {
        submit(event);
        return;
      }
      if (event.key === 'Escape' && other) {
        event.preventDefault();
        setOther(false);
        setValue('');
        otherInput.current?.focus();
        return;
      }
      if (
        kind === 'short' ||
        event.altKey ||
        event.ctrlKey ||
        event.metaKey ||
        event.shiftKey ||
        event.target.tagName === 'TEXTAREA' ||
        !/^[1-9]$/.test(event.key)
      )
        return;
      const at = Number(event.key) - 1;
      if (at === choices.length) {
        event.preventDefault();
        setOther(true);
        if (kind === 'single') setSelected([]);
      } else if (choices[at] !== undefined) {
        event.preventDefault();
        choose(choices[at], !selected.includes(choices[at]));
      }
    };
    return html`<form
      className="tmt-block-question"
      aria-label=${props.label || 'Question'}
      onSubmit=${submit}
      onKeyDown=${key}
    >
      <div className="tmt-block-question-mark" aria-hidden="true">?</div>
      <div className="tmt-block-question-content">
        ${
          props.state === 'answered' &&
          html`<button
            type="button"
            className="tmt-block-question-answered"
            aria-expanded="true"
            onClick=${() => setExpanded(false)}
          >
            ✓ ${props.label} ${props.answer}
          </button>`
        }
        <div className="tmt-block-question-eyebrow">
          ◆ Waiting for your answer · ${props.agent || ''}
        </div>
        <h3>${props.label}</h3>
        ${
          kind !== 'short' &&
          html`<fieldset className="tmt-ui-choices">
            <legend className="tmt-ui-choices-legend">Choices</legend>
            <div className="tmt-block-question-choices">
              ${choices.map(
                (choice, at) => html`<label className="tmt-ui-choice" key=${at}>
                  <input
                    type=${kind === 'multiple' ? 'checkbox' : 'radio'}
                    className=${kind === 'multiple' ? 'tmt-ui-checkbox' : 'tmt-ui-radio'}
                    name=${id}
                    checked=${selected.includes(choice)}
                    aria-label=${choice}
                    aria-keyshortcuts=${at < 9 ? String(at + 1) : undefined}
                    onChange=${(event) => choose(choice, event.target.checked)}
                  />
                  <span className="tmt-ui-choice-text">${choice}</span
                  >${at < 9 && html`<kbd aria-hidden="true">${at + 1}</kbd>`}</label
                >`,
              )}
              <label className="tmt-ui-choice"
                ><input
                  ref=${otherInput}
                  type=${kind === 'multiple' ? 'checkbox' : 'radio'}
                  className=${kind === 'multiple' ? 'tmt-ui-checkbox' : 'tmt-ui-radio'}
                  name=${id}
                  checked=${other}
                  aria-label="Other…"
                  aria-keyshortcuts=${choices.length < 9 ? String(choices.length + 1) : undefined}
                  onChange=${(event) => {
                    setOther(event.target.checked);
                    if (kind === 'single') setSelected([]);
                    if (!event.target.checked) setValue('');
                  }}
                /><span className="tmt-ui-choice-text">Other…</span
                >${choices.length < 9 && html`<kbd aria-hidden="true">${choices.length + 1}</kbd>`}</label
              >
            </div>
          </fieldset>`
        }
        ${
          (kind === 'short' || other) &&
          html`<div className="tmt-block-question-input">
            <textarea
              ref=${input}
              aria-label=${kind === 'short' ? 'Your answer' : 'Other: your answer'}
              aria-describedby=${`${id}-count`}
              placeholder="Write your answer"
              value=${value}
              onInput=${(event) => {
                const next = Array.from(event.target.value).slice(0, 200).join('');
                setValue(next);
                if (kind !== 'short' && !next && value) {
                  setOther(false);
                  otherInput.current?.focus();
                }
              }}
              rows="1"
            />
            <span id=${`${id}-count`}
              >${Array.from(value).length >= 160 ? `${Array.from(value).length} / 200` : ''}</span
            >
          </div>`
        }
        <${Button} disabled=${!valid} onClick=${submit}>Send<//>
      </div>
    </form>`;
  };

components.css:
.tmt-block-doc {
  container: tmt-block-doc / inline-size;
  min-width: 0;
  color: var(--tmt-ui-color-text);
  font: 15px / 1.6 var(--tmt-ui-font-body);
}
.tmt-block-doc-body {
  --tmt-block-gutter: 56px;
  --tmt-block-gap: 14px;
  position: relative;
  padding-inline-start: var(--tmt-block-gutter);
}
.tmt-block {
  position: relative;
  min-width: 0;
  margin-inline: -8px;
  padding: 2px 8px;
  border-radius: var(--tmt-ui-radius-s);
  outline: none;
}
.tmt-block + .tmt-block {
  margin-top: var(--tmt-block-gap);
}
.tmt-block[data-kind='heading'] {
  margin-top: 32px;
}
.tmt-block[data-kind='heading'][data-level='3'] {
  margin-top: 22px;
}
.tmt-block-doc-body > .tmt-block:first-child {
  margin-top: 0;
}
.tmt-block[data-depth='1'] {
  margin-inline: 0;
}
.tmt-block:where(:not([data-readonly])):hover,
.tmt-block[data-state='hover'] {
  background: var(--tmt-ui-surface-hover);
}
.tmt-block[data-selected],
.tmt-block[data-state='selected'] {
  background: var(--tmt-ui-surface-selection);
}
.tmt-block:focus-visible {
  outline: var(--tmt-ui-focus-width) solid var(--tmt-ui-color-focus);
  outline-offset: 2px;
}
.tmt-block[data-state='dragging'] {
  opacity: 0.4;
}
.tmt-block > :where(h2, h3, p, pre, ul, ol, table) {
  margin: 0;
}


.tmt-block-handle {
  position: absolute;
  inset-inline-start: -48px;
  top: 2px;
  display: flex;
  justify-content: flex-end;
  width: 40px;
  color: var(--tmt-ui-color-secondary);
}
.tmt-block-handle-button {
  display: inline-grid;
  place-items: center;
  width: 20px;
  height: 24px;
  padding: 0;
  border: 0;
  border-radius: var(--tmt-ui-radius-s);
  background: none;
  color: inherit;
  cursor: pointer;
}
.tmt-block-handle-button[data-grip] {
  cursor: grab;
}
.tmt-block-handle-button:hover,
.tmt-block-handle-button[aria-expanded='true'] {
  background: var(--tmt-ui-surface-sheet);
  color: var(--tmt-ui-color-text);
}
.tmt-block-handle-button:focus-visible {
  outline: var(--tmt-ui-focus-width) solid var(--tmt-ui-color-focus);
}
.tmt-block-handle svg,
.tmt-block-menu svg,
.tmt-block-code svg,
.tmt-block-mention svg {
  width: 16px;
  height: 16px;
  flex: none;
}
.tmt-block-drop {
  position: relative;
  height: 3px;
  margin: 4px 0;
  border-radius: 2px;
  background: var(--tmt-ui-color-accent);
}
.tmt-block-drop::before {
  content: '';
  position: absolute;
  inset-inline-start: -5px;
  top: -3px;
  box-sizing: border-box;
  width: 9px;
  height: 9px;
  border: 2px solid var(--tmt-ui-color-accent);
  border-radius: 50%;
  background: var(--tmt-ui-surface-sheet);
}
.tmt-block-ghost {
  position: absolute;
  z-index: 3;
  display: flex;
  gap: 8px;
  align-items: center;
  width: 260px;
  max-width: 80%;
  padding: 8px 12px;
  border: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule);
  border-radius: var(--tmt-ui-radius);
  background: var(--tmt-ui-surface-sheet);
  box-shadow: var(--tmt-ui-shadow-overlay);
  font-size: var(--tmt-ui-caption-size);
  pointer-events: none;
  transform: rotate(-1.5deg);
}


.tmt-block-menu {
  box-sizing: border-box;
  display: grid;
  gap: 1px;
  width: 300px;
  max-width: 100%;
  max-height: 360px;
  overflow-y: auto;
  padding: 6px;
  border: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule);
  border-radius: var(--tmt-ui-radius);
  background: var(--tmt-ui-surface-sheet);
  box-shadow: var(--tmt-ui-shadow-overlay);
  color: var(--tmt-ui-color-text);
  font: 14px / 1.4 var(--tmt-ui-font-body);
  outline: none;
}
.tmt-block-menu[data-placement='sheet'] {
  width: 100%;
  max-height: 60vh;
  border-width: var(--tmt-ui-rule-width) 0 0;
  border-radius: var(--tmt-ui-radius-l) var(--tmt-ui-radius-l) 0 0;
  padding: 8px 8px 12px;
}
.tmt-block-menu[data-placement='sheet']::before {
  content: '';
  display: block;
  width: 36px;
  height: 4px;
  margin: 0 auto 8px;
  border-radius: 2px;
  background: var(--tmt-ui-surface-rule);
}
.tmt-block-menu-group {
  padding: 6px 8px 2px;
  color: var(--tmt-ui-color-secondary);
  font-size: var(--tmt-ui-caption-size);
  font-weight: 600;
}
.tmt-block-menu-item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
  min-height: 32px;
  padding: 4px 8px;
  border-radius: var(--tmt-ui-radius-s);
  cursor: pointer;
}
.tmt-block-menu-item:has(> .tmt-block-menu-icon) {
  grid-template-columns: 28px minmax(0, 1fr) auto;
}
.tmt-block-menu[data-placement='sheet'] .tmt-block-menu-item {
  min-height: 44px;
}
.tmt-block-menu-item[data-active] {
  background: var(--tmt-ui-surface-selection);
  color: var(--tmt-ui-color-selected-text);
}
.tmt-block-menu-item[data-danger] {
  color: var(--tmt-ui-color-blocked);
}
.tmt-block-menu-icon {
  display: inline-grid;
  place-items: center;
  width: 28px;
  height: 28px;
  box-sizing: border-box;
  border: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule);
  border-radius: var(--tmt-ui-radius-s);
  background: var(--tmt-ui-surface-paper);
}
.tmt-block-menu-label {
  min-width: 0;
  overflow-wrap: anywhere;
}
.tmt-block-menu-description {
  display: block;
  color: var(--tmt-ui-color-secondary);
  font-size: var(--tmt-ui-caption-size);
}
.tmt-block-menu-item[data-active] .tmt-block-menu-description {
  color: inherit;
}
.tmt-block-kbd {
  padding: 0 5px;
  border: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule);
  border-radius: var(--tmt-ui-radius-s);
  color: var(--tmt-ui-color-secondary);
  font: 500 11px / 1.4 var(--tmt-ui-font-mono);
  white-space: nowrap;
}
.tmt-block-menu-separator {
  margin: 4px 0;
  border: 0;
  border-top: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule-soft);
}
.tmt-block-menu-empty {
  padding: 8px;
  color: var(--tmt-ui-color-secondary);
}
.tmt-block-menu-footer {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  padding: 6px 8px 2px;
  color: var(--tmt-ui-color-secondary);
  font-size: var(--tmt-ui-caption-size);
}


.tmt-block-heading {
  margin: 0;
  font-family: var(--tmt-ui-font-display);
  font-weight: 650;
  line-height: 1.3;
  overflow-wrap: anywhere;
}
.tmt-block-heading[data-level='2'] {
  font-size: 22px;
}
.tmt-block-heading[data-level='3'] {
  font-size: 17px;
}
.tmt-block-text {
  margin: 0;
  overflow-wrap: anywhere;
}
.tmt-block-text[data-tone='muted'] {
  color: var(--tmt-ui-color-secondary);
}
.tmt-block-text[data-empty]::before,
.tmt-block-heading[data-empty]::before {
  content: attr(data-placeholder);
  color: var(--tmt-ui-color-secondary);
}
.tmt-block-list {
  display: grid;
  grid-template-columns: 20px minmax(0, 1fr);
  gap: 4px;
  margin: 0;
  padding-inline-start: calc(var(--tmt-block-indent, 0) * 24px);
}
.tmt-block-list-marker {
  color: var(--tmt-ui-color-secondary);
  font-variant-numeric: tabular-nums;
  text-align: end;
  padding-inline-end: 4px;
}
.tmt-block-todo {
  display: grid;
  grid-template-columns: 20px minmax(0, 1fr) auto;
  gap: 4px 10px;
  align-items: start;
  padding-inline-start: calc(var(--tmt-block-indent, 0) * 24px);
}
.tmt-block-todo .tmt-ui-checkbox {
  margin: 4px 0 0;
}
.tmt-block-todo-text {
  min-width: 0;
  overflow-wrap: anywhere;
}
.tmt-block-todo[data-checked] .tmt-block-todo-text {
  color: var(--tmt-ui-color-secondary);
  text-decoration: line-through;
}
.tmt-block-todo-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
  color: var(--tmt-ui-color-secondary);
  font-size: var(--tmt-ui-caption-size);
  white-space: nowrap;
}
.tmt-block-todo[data-overdue] .tmt-block-todo-due {
  color: var(--tmt-ui-color-blocked);
}
.tmt-block-table {
  container: tmt-block-table / inline-size;
  max-height: 480px;
  overflow: auto;
}
.tmt-block-table .tmt-ui-table {
  width: 100%;
}
.tmt-block-table [data-nowrap] {
  white-space: nowrap;
}
.tmt-block-card {
  margin: 0;
  padding: 16px;
  border: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule);
  border-radius: var(--tmt-ui-radius-l);
  background: var(--tmt-ui-surface-sheet);
}
.tmt-block-card[data-variant='section'] {
  padding: 0;
  border: 0;
  background: none;
}
.tmt-block-card-head {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 12px;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 12px;
}
.tmt-block-card-title {
  min-width: 0;
  margin: 0;
  font-size: 16px;
