// This tag renders the real browser-ui BrowserAvatar supplied by runtime 4.
export default ({ React, ui }) => ({ name = '', ...props }) =>
  React.createElement(ui.BrowserAvatar, { ...props, name });

// Runtime 4 supplies the real isolated browser-ui stage. Size containment needs dimensions.
export default ({ React, ui }) => ({ width = '100%', height = '400px', children }) =>
  React.createElement(ui.DsScope, { style: { width, height } }, children);

// Runtime 4 supplies the real browser-ui checkbox; its native interaction owns the local value.
export default ({ React, ui }) => function BrowserCheckbox({ checked, children, ...props }) {
  const [value, setValue] = React.useState(checked);
  React.useEffect(() => setValue(checked), [checked]);
  return React.createElement(ui.BrowserCheckbox, {
    ...props,
    checked: value,
    onChange: (event) => setValue(event.target.checked),
  });
};

// The real BrowserAction sends its native click through the custom element.
export default ({ React, ui }) => ({ label = '', variant = 'secondary', children, ...props }) =>
  React.createElement(ui.BrowserAction, { ...props, label, variant, type: 'button', busyMark: React.createElement(ui.BusyMark), onActivate: () => {} });

// The BrowserToggle keeps its local pressed state while the page observes native clicks.
export default ({ React, ui }) => function Toggle({ label = '', pressed, children, ...props }) {
  const [value, setValue] = React.useState(pressed);
  React.useEffect(() => setValue(pressed), [pressed]);
  return React.createElement(ui.BrowserToggle, {
    ...props,
    label,
    pressed: value,
    onActivate: () => setValue((current) => !current),
  });
};

// Runtime 4 supplies the real browser-ui layer components.
export default ({ React, ui }) => function Dialog({ label = 'Open dialog', heading = 'Dialog', children }) {
  const h = React.createElement;
  return h(ui.UiTheme, null, h(ui.Dialog, null, h(ui.DialogTrigger, { asChild: true }, h(ui.Button, { variant: 'outline' }, label)),
    h(ui.DialogContent, null, h(ui.DialogTitle, null, heading), h(ui.DialogDescription, null, children))));
};

// Runtime 4 supplies the real browser-ui layer components.
export default ({ React, ui }) => function Sheet({ label = 'Open sheet', heading = 'Sheet', children }) {
  const h = React.createElement;
  return h(ui.UiTheme, null, h(ui.Sheet, null, h(ui.SheetTrigger, { asChild: true }, h(ui.Button, { variant: 'outline' }, label)),
    h(ui.SheetContent, null, h(ui.SheetTitle, null, heading), h(ui.SheetDescription, null, children))));
};

// Runtime 4 supplies the real browser-ui layer components.
export default ({ React, ui }) => function Popover({ label = 'Open popover', children }) {
  const h = React.createElement;
  return h(ui.UiTheme, null, h(ui.Popover, null, h(ui.PopoverTrigger, { asChild: true }, h(ui.Button, { variant: 'outline' }, label)),
    h(ui.PopoverContent, null, children)));
};

// Runtime 4 supplies the real browser-ui layer components.
export default ({ React, ui }) => function Menu({ label = 'Open menu', items = '' }) {
  const h = React.createElement;
  const choices = items.split(',').map((item) => item.trim()).filter(Boolean);
  return h(ui.UiTheme, null, h(ui.DropdownMenu, null, h(ui.DropdownMenuTrigger, { asChild: true }, h(ui.Button, { variant: 'outline' }, label)),
    h(ui.DropdownMenuContent, null, ...choices.map((item) => h(ui.DropdownMenuItem, { key: item }, item)))));
};

export default ({ React, ui }) => function Pager({ label = 'Page', count = '1' }) {
  const total = Math.max(1, Number.parseInt(count, 10) || 1);
  const [position, setPosition] = React.useState(1);
  return React.createElement(ui.BrowserPager, { label, position: Math.min(position, total), count: total,
    previousLabel: 'Previous', nextLabel: 'Next', onPrevious: () => setPosition((n) => Math.max(1, n - 1)),
    onNext: () => setPosition((n) => Math.min(total, n + 1)) });
};

export default ({ React, ui }) => function Choice({ label = '', type = 'checkbox', checked, children, ...props }) {
  const [value, setValue] = React.useState(checked);
  React.useEffect(() => setValue(checked), [checked]);
  return React.createElement(ui.BrowserChoice, { ...props, label, type, checked: value, onChange: (event) => setValue(event.target.checked) });
};

export default ({ React, ui }) => function Field({ label = 'Field', placeholder }) {
  const id = React.useId();
  return React.createElement(ui.BrowserField, { controlId: id, label,
    renderControl: (props) => React.createElement('input', { ...props, placeholder }) });
};

export default ({ React, ui }) => ({ label = 'Table', columns = '', rows = '' }) =>
  React.createElement(ui.BrowserTable, { label, columns: columns.split(',').map((x) => x.trim()),
    rows: rows ? rows.split(';').map((row) => row.split(',').map((x) => x.trim())) : [] });

export default ({ React, ui }) => function Tabs({ label = 'Views', items = '', children }) {
  const base = React.useId();
  const tabs = items.split(',').map((item) => item.trim()).filter(Boolean)
    .map((item, index) => ({ id: item, label: item, tabId: `${base}-tab-${index}`, panelId: `${base}-panel-${index}` }));
  const [selected, setSelected] = React.useState(tabs[0]?.id ?? '');
  return React.createElement(ui.BrowserTabs, { label, tabs, selected, onSelect: setSelected, children: () => children });
};

// Runtime 4 supplies the real Select and its parts.
export default ({ React, ui }) => function Select({ label = 'Select', items = '' }) {
  const h = React.createElement;
  const choices = items.split(',').map((item) => item.trim()).filter(Boolean);
  return h(ui.UiTheme, null, h(ui.Select, null,
    h(ui.SelectTrigger, { 'aria-label': label }, h(ui.SelectValue, { placeholder: label })),
    h(ui.SelectContent, null, ...choices.map((item) => h(ui.SelectItem, { key: item, value: item }, item)))));
};

// Runtime 4 supplies the real Tooltip and its originating theme.
export default ({ React, ui }) => function Tooltip({ label = 'Help', children }) {
  const h = React.createElement;
  return h(ui.UiTheme, null, h(ui.TooltipProvider, null, h(ui.Tooltip, null,
    h(ui.TooltipTrigger, { asChild: true }, h(ui.Button, { variant: 'outline' }, label)),
    h(ui.TooltipContent, null, children))));
};

// Compose the real command palette parts on the page runtime's React.
export default ({ React, ui }) => function Command({ label = 'Search', items = '' }) {
  const h = React.createElement;
  const choices = items.split(',').map((item) => item.trim()).filter(Boolean);
  return h(ui.Command, { label }, h(ui.CommandInput, { placeholder: label, 'aria-label': label }),
    h(ui.CommandList, null, ...choices.map((item) => h(ui.CommandItem, { key: item }, item))));
};

// Compose the real floating dock and window, retaining local open state.
export default ({ React, ui }) => function Floating({ label = 'Chat', children }) {
  const [open, setOpen] = React.useState(false);
  const h = React.createElement;
  return h(ui.UiTheme, null, h(ui.TooltipProvider, null, h(ui.FloatingDock, null,
    h(ui.FloatingWindow, { open, label, onClose: () => setOpen(false) }, children),
    h(ui.FloatingActions, { label: 'Actions' }, h(ui.FloatingAction, {
      label, icon: '●', expanded: open, onClick: () => setOpen((value) => !value),
    })))));
};

// The real Chips control owns its layer; the example keeps a local selection.
export default ({ React, ui }) => {
  const h = React.createElement;
  function Control({ label, choices }) {
    const [open, setOpen] = React.useState(false);
    const [query, setQuery] = React.useState('');
    const [items, setItems] = React.useState([]);
    const controller = ui.useLayerController({ open, onOpenChange: setOpen });
    const options = choices.filter((name) => !items.includes(name) && name.toLowerCase().includes(query.toLowerCase()))
      .map((name) => ({ id: name, label: name }));
    return h(ui.Chips, { label, controller, query, onQueryChange: setQuery, options,
      emptyLabel: 'No matches', items: items.map((name) => ({ id: name, label: name, removeLabel: `Remove ${name}` })),
      onAdd: (option) => { setItems((current) => [...current, option.id]); setQuery(''); },
      onRemove: (item) => setItems((current) => current.filter((name) => name !== item.id)) });
  }
  return ({ label = 'People', items = '' }) => h(ui.UiTheme, null,
    h(Control, { label, choices: items.split(',').map((item) => item.trim()).filter(Boolean) }));
};

// The real DataTable receives a small page-authored projection.
export default ({ React, ui }) => ({ label = 'Table', columns = 'Name', rows = '' }) => {
  const headings = columns.split(',').map((value) => value.trim()).filter(Boolean);
  const entries = rows ? rows.split(';').map((row, id) => ({ id: String(id), cells: row.split(',').map((value) => value.trim()) })) : [];
  const fields = headings.map((header, index) => ({ id: String(index), header, role: index === 0 ? 'primary' : 'text', text: (row) => row.cells[index] ?? '' }));
  return React.createElement(ui.UiTheme, null, React.createElement(ui.DataTable, { label, rows: entries, columns: fields,
    rowKey: (row) => row.id, rowLabel: (row) => row.cells[0] ?? '' }));
};

// PageListTable is host supplied because it can consume the bounded page projection.
export default ({ React, parts }) => ({ rows = '', live = false }) => {
  const entries = rows ? rows.split(';').map((row, id) => {
    const [name, state = ''] = row.split(',').map((value) => value.trim());
    return { id: String(id), name, title: name, projects: [], stage: { id: state, label: state }, updated: '', author: '', access: '' };
  }) : [];
  return React.createElement(parts.PageListTable, { rows: entries, livePageView: live });
};

// Runtime 4 supplies the real browser-ui rich input, with local editing state.
export default ({ React, ui }) => function RichInput({ label = 'Message', shape = 'multi', placeholder, disabled }) {
  const [value, setValue] = React.useState({ value: '', chips: [] });
  return React.createElement(ui.RichInput, { label, shape, placeholder, disabled, value, onChange: setValue });
};

// The real BrowserChips control keeps its example's selection locally.
export default ({ React, ui }) => function BrowserChips({ label = 'People', items = '' }) {
  const [selected, setSelected] = React.useState([]);
  const [query, setQuery] = React.useState('');
  const options = items.split(',').map((item) => item.trim()).filter(Boolean)
    .filter((item) => !selected.includes(item) && item.toLowerCase().includes(query.toLowerCase()))
    .map((item) => ({ id: item, label: item }));
  return React.createElement(ui.BrowserChips, { label, query, onQueryChange: setQuery, options,
    items: selected.map((item) => ({ id: item, label: item, removeLabel: `Remove ${item}` })),
    addLabel: 'Add', searchLabel: 'Search', emptyText: 'No matches',
    onAdd: (id) => { setSelected((current) => [...current, id]); setQuery(''); },
    onRemove: (id) => setSelected((current) => current.filter((item) => item !== id)) });
};

// The selected real Browser overlay retains its open state locally.
export default ({ React, ui }) => function Overlay({ label = 'Details', kind = 'dialog', children }) {
  const [open, setOpen] = React.useState(false);
  const h = React.createElement;
  const Part = kind === 'drawer' ? ui.BrowserDrawer : kind === 'panel' ? ui.BrowserPanel : ui.BrowserDialog;
  return h(ui.UiTheme, null, h(ui.BrowserAction, { type: 'button', label: `Open ${label}`, variant: 'secondary', onActivate: () => setOpen(true) }),
    h(Part, { open, title: label, mode: kind === 'panel' ? 'card' : undefined, onDismiss: () => setOpen(false) }, children));
};

// The real shell renders the page-authored rail inside its originating stage.
export default ({ React, ui }) => function Shell({ items = 'Colab,Design', children }) {
  const main = items.split(',').map((item) => item.trim()).filter(Boolean).map((label, index) => ({
    id: String(index), label, icon: 'box', href: '#', current: index === 0,
  }));
  return React.createElement(ui.UiTheme, null, React.createElement(ui.BrowserShell,
    { view: { rail: { main, bottom: [] } }, select: () => true }, children));
};

// The real notifications surface receives an example event when activated.
export default ({ React, ui }) => function Notifications({ label = 'Notify', message = 'A reply arrived' }) {
  const [events, setEvents] = React.useState([]);
  const h = React.createElement;
  return h(React.Fragment, null,
    h(ui.BrowserAction, { type: 'button', label, variant: 'secondary', onActivate: () => setEvents([{ id: String(Date.now()), destination: 'Chat', firstLine: message, onActivate: () => {} }]) }),
    h(ui.BrowserNotifications, { pageKey: 'example', events, suspended: false, isEligible: () => true }));
};

export default ({ React, ui }) => ({ label = 'Chart', values = '' }) => {
  const points = values.split(',').map((value) => Number(value.trim())).filter(Number.isFinite);
  return React.createElement(ui.BrowserChart, { options: { title: label, kind: 'line',
    x: points.map((_, index) => String(index + 1)), series: [{ key: 'series', label, values: points }] } });
};

export default ({ React, ui }) => function PageRow({ label = 'Page', tags = '', updated = '', state, href = '#', unread }) {
  return React.createElement(ui.BrowserPageRow, { title: label, tags: tags.split(',').map((tag) => tag.trim()).filter(Boolean), updated, state, href, unread });
};

components.css:
.docs-status {
  display: flex;
  flex-wrap: wrap;
  gap: var(--tmt-ui-ref-space-5);
  margin: 0;
  padding: 0;
  list-style: none;
  font-weight: 600;
}
.pattern-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto 96px;
  align-items: center;
  gap: var(--tmt-ui-ref-space-4);
  padding: var(--tmt-ui-ref-space-3) var(--tmt-ui-ref-space-4);
  border-bottom: var(--tmt-ui-rule-width) solid var(--tmt-ui-surface-rule);
  text-decoration: none;
}
.pattern-row:last-child {
  border-bottom: 0;
}
.pattern-row:hover {
  background: var(--tmt-ui-surface-hover);
}
.pattern-row-title {
  overflow: hidden;
  color: var(--tmt-ui-color-secondary);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.pattern-row[data-unread] .pattern-row-title {
  color: var(--tmt-ui-color-selected-text);
  font-weight: 700;
}
.pattern-row-tags {
  display: flex;
  gap: var(--tmt-ui-ref-space-1);
}
.pattern-row-time {
  color: var(--tmt-ui-color-secondary);
  font-size: var(--tmt-ui-ref-size-2);
  text-align: right;
}
.pattern-state {
  margin-right: var(--tmt-ui-ref-space-2);
}
.pattern-state[data-tone='waiting'] {
  color: var(--tmt-ui-color-waiting);
}
.pattern-state[data-tone='blocked'] {
  color: var(--tmt-ui-color-blocked);
}
.pattern-band {
  padding: 0;
}
.pattern-band-bar {
  display: flex;
  align-items: center;
  gap: var(--tmt-ui-ref-space-3);
  width: 100%;
  height: 44px;
  padding: 0 var(--tmt-ui-ref-space-4);
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  cursor: pointer;
}
.pattern-meter {
  overflow: hidden;
  width: 160px;
  height: 4px;
  border-radius: var(--tmt-ui-radius-pill);
  background: var(--tmt-ui-surface-rule);
}
.pattern-meter > span {
  display: block;
  height: 100%;
  background: var(--tmt-ui-color-working);
}
.pattern-chevron {
  width: 16px;
  height: 16px;
  margin-left: auto;
}
.pattern-chevron[data-open] {
  rotate: 180deg;
}
.pattern-band-pages {
  margin: 0;
  padding: 0 var(--tmt-ui-ref-space-4) var(--tmt-ui-ref-space-3);
  list-style: none;
}
.pattern-band-pages li {
  display: grid;
  grid-template-columns: 16px minmax(0, 1fr) auto auto;
  align-items: center;
  gap: var(--tmt-ui-ref-space-3);
  min-height: 32px;
}
.pattern-band-pages svg {
  width: 16px;
  height: 16px;
}
.pattern-band-pages li:last-child {
  display: block;
}
.pattern-turns {
  display: grid;
  gap: var(--tmt-ui-ref-space-4);
  max-width: 520px;
}
.pattern-turn p {
  margin: var(--tmt-ui-ref-space-1) 0;
}
.pattern-turn[data-state='sending'] p,
.pattern-turn[data-state='unsent'] p {
  color: var(--tmt-ui-color-secondary);
}
.pattern-inline {
  display: inline-flex;
  align-items: center;
  gap: var(--tmt-ui-ref-space-2);
}
.pattern-failed {
  color: var(--tmt-ui-color-blocked);
}
@media (max-width: 760px) {
  .pattern-row:not([data-tmt-ds-scope] *) {
    grid-template-columns: minmax(0, 1fr) auto;
  }
}
